pp: E[2][1]; pq: E[2][2]; er: E[7]; keyv: E[8]; wrong: E[9]; ord: E[10]; t: E[11]; sv: E[12]; Pv: E[13]; hint: E[14]; bst: E[15]; whyl: E[16];
otext(k) := if k = "e1" then "He rounded the vertex to the nearest whole numbers, but that point is outside R." elseif k = "e2" then "He rounded both numbers down, but another whole-number point gives more." elseif k = "e3" then "He chose the vertex with the smallest value of P." else "His answer is the value at a vertex that is not a whole-number point.";
o1: append([["ok", false, "His working is correct."]], makelist([ord[j], is(ord[j] = keyv), otext(ord[j])], j, 1, 4));
